--- /dev/null
+++ b/src/ui/lib/focus.ts
@@ -0,0 +1,207 @@
+import { focusAnchor, holdingHunk, noteAnchor, noteLetter } from "../../schema/anchor.ts";
+import type { DiffLine, FocusRange, LineNote } from "../../schema/types.ts";
+import type { LiveHunk } from "../api.ts";
+
+/** A hunk that opens on its focus ranges. */
+export type HunkFocus = {
+  /** Index into the file's hunks. */
+  hunk: number;
+  ranges: FocusRange[];
+  /** Indexes into the hunk's lines that the ranges show, ascending. */
+  shown: number[];
+};
+
+export type LetteredNote = LineNote & { letter: string };
+
+export function letterNotes(notes: readonly LineNote[]): LetteredNote[] {
+  return notes.map((note, i) => ({ ...note, letter: noteLetter(i) }));
+}
+
+export function onFile(
+  anchor: { path: string },
+  file: { path: string; oldPath?: string },
+): boolean {
+  return anchor.path === file.path || anchor.path === file.oldPath;
+}
+
+/** One entry per hunk that holds a focus range. A range outside every hunk is ignored: git wins. */
+export function fileFocus(hunks: readonly LiveHunk[], focus: readonly FocusRange[]): HunkFocus[] {
+  const byHunk = new Map<number, HunkFocus>();
+  for (const range of focus) {
+    const holder = holdingHunk(hunks, focusAnchor(range));
+    if (holder === undefined) {
+      continue;
+    }
+    const index = hunks.indexOf(holder);
+    const entry = byHunk.get(index) ?? { hunk: index, ranges: [], shown: [] };
+    entry.ranges.push(range);
+    entry.shown = [...new Set([...entry.shown, ...rangeLines(holder.lines, range)])].sort(
+      (a, b) => a - b,
+    );
+    byHunk.set(index, entry);
+  }
+  return [...byHunk.values()].sort((a, b) => a.hunk - b.hunk);
+}
+
+/**
+ * The lines a range names on its side. A change block cut at the range's edge widens to the whole
+ * block when the cut-off part holds the other side: a range that starts on an added line also
+ * shows the deletions that block replaces. A block of only additions stays cut.
+ */
+export function rangeLines(lines: readonly DiffLine[], range: FocusRange): number[] {
+  const number = (line: DiffLine) => (range.side === "old" ? line.oldNumber : line.newNumber);
+  const inside = lines.map((line) => {
+    const n = number(line);
+    return n !== null && n >= range.start && n <= range.end;
+  });
+  let first = inside.indexOf(true);
+  let last = inside.lastIndexOf(true);
+  if (first === -1) {
+    return [];
+  }
+  const changed = (index: number) => {
+    const kind = lines[index]?.kind;
+    return kind !== undefined && kind !== "ctx";
+  };
+  const other = range.side === "old" ? "add" : "del";
+  const pairs = (from: number, to: number) =>
+    lines.slice(from, to + 1).some((line) => line.kind === other);
+  let blockStart = first;
+  while (changed(first) && changed(blockStart - 1)) blockStart -= 1;
+  if (pairs(blockStart, first - 1)) {
+    first = blockStart;
+  }
+  let blockEnd = last;
+  while (changed(last) && changed(blockEnd + 1)) blockEnd += 1;
+  if (pairs(last + 1, blockEnd)) {
+    last = blockEnd;
+  }
+  return Array.from({ length: last - first + 1 }, (_, i) => first + i);
+}
+
+/** What a file with focus ranges renders, top to bottom. */
+export type FocusBlock =
+  | { kind: "bar"; key: string; hunk: number; focus: HunkFocus; whole: boolean }
+  | { kind: "diff"; key: string; patch: string }
+  | {
+      kind: "hidden";
+      key: string;
+      hunk: number;
+      count: number;
+      where: "above" | "between" | "below";
+      notes: LetteredNote[];
+    };
+
+/**
+ * One diff per focused hunk, so each focus bar sits on its hunk. A cut hunk shows its ranges, with
+ * a hidden-lines row at each cut edge that names the notes it hides. Undefined when no hunk has a
+ * range, or when the patch's `@@` lines do not line up with `hunks`: the file then renders whole.
+ */
+export function focusBlocks(
+  patch: string,
+  hunks: readonly LiveHunk[],
+  focus: readonly HunkFocus[],
+  whole: ReadonlySet<number>,
+  notes: readonly LetteredNote[],
+): FocusBlock[] | undefined {
+  const lines = patch.replace(/\n$/, "").split("\n");
+  const starts = lines.flatMap((line, i) => (line.startsWith("@@ ") ? [i] : []));
+  if (focus.length === 0 || starts.length !== hunks.length || starts[0] === undefined) {
+    return undefined;
+  }
+  const header = lines.slice(0, starts[0]);
+  const diff = (key: string, body: readonly string[]): FocusBlock => ({
+    kind: "diff",
+    key,
+    patch: `${[...header, ...body].join("\n")}\n`,
+  });
+  const blocks: FocusBlock[] = [];
+  // Hunks with no range read together as one diff, as they do in a file with no focus.
+  let plain: string[] = [];
+  const flush = (i: number) => {
+    if (plain.length > 0) {
+      blocks.push(diff(`plain-${i}`, plain));
+      plain = [];
+    }
+  };
+  hunks.forEach((hunk, i) => {
+    const chunk = lines.slice(starts[i], starts[i + 1] ?? lines.length);
+    const entry = focus.find((item) => item.hunk === i);
+    if (entry === undefined) {
+      plain.push(...chunk);
+      return;
+    }
+    flush(i);
+    const isWhole = whole.has(i);
+    blocks.push({ kind: "bar", key: `bar-${i}`, hunk: i, focus: entry, whole: isWhole });
+    if (isWhole) {
+      blocks.push(diff(`hunk-${i}`, chunk));
+      return;
+    }
+    const hidden = (where: "above" | "between" | "below", from: number, to: number) => {
+      if (to < from) {
+        return;
+      }
+      const cutLines = hunk.lines.slice(from, to + 1);
+      blocks.push({
+        kind: "hidden",
+        key: `hidden-${i}-${from}`,
+        hunk: i,
+        count: cutLines.length,
+        where,
+        notes: notes.filter(
+          (note) =>
+            onHunk(note, hunk) &&
+            cutLines.some(
+              (line) => (note.side === "old" ? line.oldNumber : line.newNumber) === note.line,
+            ),
+        ),
+      });
+    };
+    const cut = runs(entry.shown);
+    cut.forEach((run, j) => {
+      const first = run[0] ?? 0;
+      const previous = cut[j - 1]?.at(-1);
+      hidden(j === 0 ? "above" : "between", previous === undefined ? 0 : previous + 1, first - 1);
+      blocks.push(diff(`cut-${i}-${first}`, subHunk(hunk, run)));
+    });
+    hidden("below", (cut.at(-1)?.at(-1) ?? -1) + 1, hunk.lines.length - 1);
+  });
+  flush(hunks.length);
+  return blocks;
+}
+
+function onHunk(note: LineNote, hunk: LiveHunk): boolean {
+  return holdingHunk([hunk], noteAnchor(note)) !== undefined;
+}
+
+function runs(indexes: readonly number[]): number[][] {
+  const out: number[][] = [];
+  for (const index of indexes) {
+    const run = out.at(-1);
+    if (run !== undefined && run.at(-1) === index - 1) {
+      run.push(index);
+    } else {
+      out.push([index]);
+    }
+  }
+  return out;
+}
+
+const MARK = { ctx: " ", add: "+", del: "-" } as const;
+
+function subHunk(hunk: LiveHunk, run: readonly number[]): string[] {
+  const first = run[0] ?? 0;
+  const before = hunk.lines.slice(0, first);
+  const picked = run.flatMap((i) => hunk.lines[i] ?? []);
+  const count = (list: readonly DiffLine[], side: "oldNumber" | "newNumber") =>
+    list.filter((line) => line[side] !== null).length;
+  // An empty side starts on the line before the excerpt, as git writes it. A hunk that is empty on
+  // that side already names that line.
+  const start = (hunkStart: number, hunkLines: number, side: "oldNumber" | "newNumber") => {
+    const at = hunkStart + count(before, side);
+    return count(picked, side) === 0 && hunkLines > 0 ? at - 1 : at;
+  };
+  const header = `@@ -${start(hunk.oldStart, hunk.oldLines, "oldNumber")},${count(picked, "oldNumber")} +${start(hunk.newStart, hunk.newLines, "newNumber")},${count(picked, "newNumber")} @@`;
+  return [header, ...picked.map((line) => `${MARK[line.kind]}${line.text}`)];
+}

diff --git a/src/ui/lib/focus.test.ts b/src/ui/lib/focus.test.ts
new file mode 100644
index 0000000..cf63d4a
--- /dev/null
+++ b/src/ui/lib/focus.test.ts
@@ -0,0 +1,145 @@
+import assert from "node:assert/strict";
+import { describe, it } from "vite-plus/test";
+import type { FocusRange } from "../../schema/types.ts";
+import type { LiveHunk } from "../api.ts";
+import { fileFocus, focusBlocks, letterNotes, type FocusBlock } from "./focus.ts";
+
+function hunk(oldStart: number, newStart: number, body: string[]): LiveHunk {
+  let oldNumber = oldStart;
+  let newNumber = newStart;
+  const lines = body.map((raw) => {
+    const text = raw.slice(1);
+    if (raw.startsWith("+")) {
+      return { kind: "add" as const, oldNumber: null, newNumber: newNumber++, text };
+    }
+    if (raw.startsWith("-")) {
+      return { kind: "del" as const, oldNumber: oldNumber++, newNumber: null, text };
+    }
+    return { kind: "ctx" as const, oldNumber: oldNumber++, newNumber: newNumber++, text };
+  });
+  return {
+    path: "a.ts",
+    oldStart,
+    oldLines: oldNumber - oldStart,
+    newStart,
+    newLines: newNumber - newStart,
+    header: `@@ -${oldStart},${oldNumber - oldStart} +${newStart},${newNumber - newStart} @@`,
+    language: "typescript",
+    lines,
+  };
+}
+
+function patchOf(hunks: { header: string; body: string[] }[]): string {
+  return `diff --git a/a.ts b/a.ts\n--- a/a.ts\n+++ b/a.ts\n${hunks.map((h) => [h.header, ...h.body].join("\n")).join("\n")}\n`;
+}
+
+const firstBody = [" a", " b", "-old", "+new1", "+new2", " c", "-gone", " d", "+tail"];
+const secondBody = [" x", "+y"];
+const first = hunk(10, 10, firstBody);
+const second = hunk(40, 41, secondBody);
+const patch = patchOf([
+  { header: first.header, body: firstBody },
+  { header: second.header, body: secondBody },
+]);
+
+function range(start: number, end: number, side: "old" | "new" = "new"): FocusRange {
+  return { path: "a.ts", side, start, end, caption: "c" };
+}
+
+const FILE_HEADER = "diff --git a/a.ts b/a.ts\n--- a/a.ts\n+++ b/a.ts\n";
+
+/** Each block as one readable line: a bar, a hidden-lines row, or the diff body under the header. */
+function view(blocks: readonly FocusBlock[] | undefined): string[] | undefined {
+  return blocks?.map((block) =>
+    block.kind === "bar"
+      ? `bar ${block.hunk}${block.whole ? " whole" : ""}`
+      : block.kind === "hidden"
+        ? `hidden ${block.where} ${block.count}${block.notes.map((note) => ` ${note.letter}`).join("")}`
+        : block.patch.slice(FILE_HEADER.length).trimEnd().split("\n").join(" | "),
+  );
+}
+
+describe("focus", () => {
+  it("cuts a hunk to its range plus the deletions an added line replaces, with a row at each cut edge", () => {
+    const focus = fileFocus([first, second], [range(12, 13)]);
+    assert.deepEqual(
+      focus.map((item) => [item.hunk, item.shown]),
+      [[0, [2, 3, 4]]],
+    );
+    assert.deepEqual(view(focusBlocks(patch, [first, second], focus, new Set(), [])), [
+      "bar 0",
+      "hidden above 2",
+      "@@ -12,1 +12,2 @@ | -old | +new1 | +new2",
+      "hidden below 4",
+      `${second.header} | ${secondBody.join(" | ")}`,
+    ]);
+  });
+
+  it("splits two ranges with a row between, and ignores a range outside every hunk", () => {
+    const focus = fileFocus([first, second], [range(10, 10), range(14, 15), range(90, 91)]);
+    assert.deepEqual(focus[0]?.shown, [0, 5, 6, 7]);
+    assert.equal(focus.length, 1);
+    assert.deepEqual(view(focusBlocks(patch, [first, second], focus, new Set(), [])), [
+      "bar 0",
+      "@@ -10,1 +10,1 @@ |  a",
+      "hidden between 4",
+      "@@ -13,3 +14,2 @@ |  c | -gone |  d",
+      "hidden below 1",
+      `${second.header} | ${secondBody.join(" | ")}`,
+    ]);
+  });
+
+  it("shows the whole hunk under its bar, and renders whole when no hunk has a range", () => {
+    const focus = fileFocus([first, second], [range(12, 13)]);
+    assert.deepEqual(view(focusBlocks(patch, [first, second], focus, new Set([0]), [])), [
+      "bar 0 whole",
+      `${first.header} | ${firstBody.join(" | ")}`,
+      `${second.header} | ${secondBody.join(" | ")}`,
+    ]);
+    assert.equal(focusBlocks(patch, [first, second], [], new Set(), []), undefined);
+  });
+
+  it("reads an old-side range on old line numbers and brings the paired additions", () => {
+    const focus = fileFocus([first], [range(12, 12, "old")]);
+    assert.deepEqual(focus[0]?.shown, [2, 3, 4]);
+  });
+
+  it("shows the whole change block when a range starts inside it", () => {
+    const block = hunk(5, 5, [" a", "-x", "-y", "+X", "+Y", "+Z", " b"]);
+    assert.deepEqual(fileFocus([block], [range(7, 8)])[0]?.shown, [1, 2, 3, 4, 5]);
+    assert.deepEqual(fileFocus([block], [range(7, 7, "old")])[0]?.shown, [2, 3, 4, 5]);
+  });
+
+  it("writes git's start line on an empty side, for a new file and for an insertion", () => {
+    const added = hunk(0, 1, ["+one", "+two", "+three", "+four"]);
+    const newFile = patchOf([{ header: added.header, body: ["+one", "+two", "+three", "+four"] }]);
+    assert.deepEqual(
+      view(focusBlocks(newFile, [added], fileFocus([added], [range(3, 4)]), new Set(), [])),
+      ["bar 0", "hidden above 2", "@@ -0,0 +3,2 @@ | +three | +four"],
+    );
+    const inserted = hunk(7, 7, [" a", "+b", "+c"]);
+    const insertedPatch = patchOf([{ header: inserted.header, body: [" a", "+b", "+c"] }]);
+    assert.deepEqual(
+      view(
+        focusBlocks(insertedPatch, [inserted], fileFocus([inserted], [range(9, 9)]), new Set(), []),
+      ),
+      ["bar 0", "hidden above 2", "@@ -7,0 +9,1 @@ | +c"],
+    );
+  });
+
+  it("names on each hidden row the notes it hides, and leaves a note on a shown line to its pin", () => {
+    const focus = fileFocus([first], [range(12, 13)]);
+    const notes = letterNotes([
+      { path: "a.ts", side: "new", line: 13, body: "shown" },
+      { path: "a.ts", side: "new", line: 16, body: "hidden below" },
+      { path: "a.ts", side: "old", line: 10, body: "hidden above" },
+    ]);
+    const firstPatch = patchOf([{ header: first.header, body: firstBody }]);
+    assert.deepEqual(view(focusBlocks(firstPatch, [first], focus, new Set(), notes)), [
+      "bar 0",
+      "hidden above 2 C",
+      "@@ -12,1 +12,2 @@ | -old | +new1 | +new2",
+      "hidden below 4 B",
+    ]);
+  });
+});

